content.content:
.
..
rules
settings.json
---
{
  "permissions": {
    "allow": [
      "Bash(python quicktest.py *)",
      "Bash(.venv/bin/python quicktest.py *)",
      "Bash(git diff *)",
      "Bash(git log *)",
      "Bash(git status *)"
    ],
    "deny": [
      "Edit(helpdesk/migrations/**)",
      "Edit(.github/**)",
      "Read(.env*)"
    ]
  },
  "hooks": {
    "PostToolUse": [
      {
        "matcher": "Edit|Write",
        "hooks": [
          {
            "type": "command",
            "command": "scripts/test-touched.sh"
          }
        ]
      }
    ],
    "Stop": [
      {
        "hooks": [
          {
            "type": "command",
            "command": "scripts/full-suite-gate.sh"
          }
        ]
      }
    ]
  }
}

